<?php declare(strict_types = 1);

namespace BenchNullsafeChainWalk;

/**
 * Bench for the per-level cost of NullsafeShortCircuitingHelper::getType().
 * Every property fetch / method call / array dim fetch resolves its type by
 * walking down to the chain root to detect a nullsafe operator, so a chain of
 * depth N costs O(N²) walk steps — for plain chains without any nullsafe
 * operator too. Wrapping the chain in a loop multiplies the walks further:
 * every convergence pass re-resolves the chain on a fresh scope while
 * one-time per-node costs (printed expression keys) stay cached.
 * Iterating inside the helper instead of recursing roughly halves the
 * per-step cost, which dominates on deep chains.
 */
final class Node
{

	public Node $next;

	/** @var array<int, Node> */
	public array $list = [];

	public function __construct(Node $next)
	{
		$this->next = $next;
	}

	public function next(): Node
	{
		return $this->next;
	}

}

